import{_ as s,l,o as e,c as i,v as t,p as n,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"活锁与饥饿","description":"","frontmatter":{"title":"活锁与饥饿","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/livelock-starvation.md","filePath":"cs/livelock-starvation.md","lastUpdated":1789023840000}'),h={name:"cs/livelock-starvation.md"};function E(m,a,A,_,B,f){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="活锁与饥饿" tabindex="-1">活锁与饥饿 <a class="header-anchor" href="#活锁与饥饿" aria-label="Permalink to &quot;活锁与饥饿&quot;">​</a></h1><div class="epigraph"><p>活锁是大家都在变、却谁也做不成；饥饿是调度或锁策略永远不把资源分给某位等待者——两者都不是 Coffman 环。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Tanenbaum MOS 整理</footer></div><p><a href="/cs/banker-algorithm">上一课</a>用安全序列挡住走向死锁的分配。仍可能：协议互相「请对方先走」以至于无限重试，或低优先级/低权重永远选不上。缺口是把 <strong>活锁</strong>与<strong>饥饿</strong>从死锁里拆出来：图中无环，进度仍失败。<a href="/cs/fcfs-sjf">SJF</a> 与<a href="/cs/rwlock">rwlock</a> 已经点过饥饿，本课收成同步课的收口之一。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>死锁：等待集合永远不变。活锁：状态一直变（CAS 失败重来、以太网退避又碰撞、两人在走廊对让），没有人完成临界区。饥饿：系统整体有进度，某一个任务的等待无上界。缺口不是再跑银行家矩阵，而是<strong>进度的粒度</strong>：系统级、锁级、任务级。</p><p><span class="marginnote">无锁算法常保证无锁进度（有人能完成）而不保证无等待（每个人有限步完成）。后者失败可以是饥饿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>活锁对策：随机退避、指定仲裁者、MCS 那种 FIFO 排队。饥饿对策：老化（等待越久优先级越高）、MLFQ 定期提升、写者优先 rwlock、CFS 的 vruntime 不让人的份额落到零。实时固定优先级<strong>故意</strong>允许低优先级饥饿，那是期限换来的。本课只对照，不改 RM 界限。</p>',8)),(e(),n(p,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DL%5B%22%E6%AD%BB%E9%94%81%3A%20%E7%8E%AF%2C%20%E7%8A%B6%E6%80%81%E5%86%BB%E4%BD%8F%22%5D%20--%3E%20CONTRAST%5B%22%E5%AF%B9%E7%85%A7%22%5D%0A%20%20LL%5B%22%E6%B4%BB%E9%94%81%3A%20%E5%9C%A8%E5%8A%A8%E4%BD%86%E6%97%A0%E8%BF%9B%E5%B1%95%22%5D%20--%3E%20CONTRAST%0A%20%20ST%5B%22%E9%A5%A5%E9%A5%BF%3A%20%E6%95%B4%E4%BD%93%E5%9C%A8%E8%BF%9B%E5%B1%95%2C%20%E6%9F%90%E4%BD%8D%E6%B2%A1%E6%9C%89%22%5D%20--%3E%20CONTRAST%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/restart-syscall">重启系统调用</a>：无限 EINTR 循环若每次都失败，对应用也像活锁，那是信号政策。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三种失败要不同工具：死锁查环或破条件；活锁改协议对称性；饥饿改公平或老化。银行家不管活锁：状态可以一直安全却没有人的请求被批准，若批准规则本身偏向某人。锁顺序下一课专管循环等待，不治饥饿。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把以太网 CSMA 的全部历史当 OS 正文，不讨论如何用活锁做拒绝服务。也不把优先级反转单列为第四种：它更接近「有界或无界延迟」，可与饥饿重叠。</p><p>后课默认：无环也可以没有进度。预防循环等待的工程手段是全局锁序，下一课锁顺序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>活锁：在动无进展；饥饿：有人永远轮空；都不是死锁环。</li><li>对策分别是仲裁/FIFO 与老化/公平份额。</li><li>锁顺序破循环等待，下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',8))])}const T=s(h,[["render",E]]);export{u as __pageData,T as default};
